// Independent X11/Xdnd v5 source for native acceptance, including INCR payloads.
// Build: cc native-xdnd-source.c -lX11 -o native-xdnd-source
#include <X11/Xlib.h>
#include <X11/Xatom.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <poll.h>
#include <unistd.h>

static long long millis(void){struct timespec now;clock_gettime(CLOCK_MONOTONIC,&now);return (long long)now.tv_sec*1000+now.tv_nsec/1000000;}
static void message(Display*d,Window to,Atom type,Window from,long a,long b,long c,long e){XEvent event={0};event.xclient.type=ClientMessage;event.xclient.display=d;event.xclient.window=to;event.xclient.message_type=type;event.xclient.format=32;event.xclient.data.l[0]=from;event.xclient.data.l[1]=a;event.xclient.data.l[2]=b;event.xclient.data.l[3]=c;event.xclient.data.l[4]=e;XSendEvent(d,to,False,NoEventMask,&event);XFlush(d);}
int main(int argc,char**argv){if(argc!=4){fprintf(stderr,"target-window MIME payload-file required\n");return 2;}FILE*f=fopen(argv[3],"rb");if(!f)return 2;fseek(f,0,SEEK_END);long length=ftell(f);rewind(f);if(length<0||length>64*1024*1024)return 2;unsigned char*bytes=malloc(length?length:1);if(!bytes||fread(bytes,1,length,f)!=(size_t)length)return 2;fclose(f);Display*d=XOpenDisplay(NULL);if(!d)return 2;Window target=strtoul(argv[1],NULL,0),root=DefaultRootWindow(d);Window source=XCreateSimpleWindow(d,root,0,0,1,1,0,0,0);Atom enter=XInternAtom(d,"XdndEnter",False),position=XInternAtom(d,"XdndPosition",False),status=XInternAtom(d,"XdndStatus",False),drop=XInternAtom(d,"XdndDrop",False),finished=XInternAtom(d,"XdndFinished",False),selection=XInternAtom(d,"XdndSelection",False),copy=XInternAtom(d,"XdndActionCopy",False),mime=XInternAtom(d,argv[2],False),incr=XInternAtom(d,"INCR",False);XSetSelectionOwner(d,selection,source,CurrentTime);int x,y;Window child;XWindowAttributes attributes;XGetWindowAttributes(d,target,&attributes);XTranslateCoordinates(d,target,root,attributes.width/2,attributes.height/2,&x,&y,&child);message(d,target,enter,source,5L<<24,mime,0,0);message(d,target,position,source,0,((unsigned)(x&65535)<<16)|(y&65535),CurrentTime,copy);long long deadline=millis()+5000;Window receiver=0;Atom property=None;long offset=0;int accepted=0,ok=0,transferring=0;
    while(millis()<deadline){while(XPending(d)){XEvent event;XNextEvent(d,&event);if(event.type==ClientMessage&&event.xclient.message_type==status){if(!(event.xclient.data.l[1]&1)){fprintf(stderr,"drop rejected\n");goto done;}accepted=1;message(d,target,drop,source,0,CurrentTime,0,0);}else if(event.type==SelectionRequest){XSelectionRequestEvent*r=&event.xselectionrequest;XEvent reply={0};reply.xselection.type=SelectionNotify;reply.xselection.display=d;reply.xselection.requestor=r->requestor;reply.xselection.selection=r->selection;reply.xselection.target=r->target;reply.xselection.time=r->time;reply.xselection.property=r->property;if(r->target!=mime||r->selection!=selection){reply.xselection.property=None;}else if(length<=65536){XChangeProperty(d,r->requestor,r->property,mime,8,PropModeReplace,bytes,length);}else{receiver=r->requestor;property=r->property;XSelectInput(d,receiver,PropertyChangeMask);unsigned long size=length;XChangeProperty(d,receiver,property,incr,32,PropModeReplace,(unsigned char*)&size,1);transferring=1;}XSendEvent(d,r->requestor,False,NoEventMask,&reply);XFlush(d);}else if(event.type==PropertyNotify&&transferring&&event.xproperty.window==receiver&&event.xproperty.atom==property&&event.xproperty.state==PropertyDelete){long count=length-offset;if(count>65536)count=65536;XChangeProperty(d,receiver,property,mime,8,PropModeReplace,bytes+offset,count);offset+=count;if(!count)transferring=0;XFlush(d);}else if(event.type==ClientMessage&&event.xclient.message_type==finished){ok=accepted&&(event.xclient.data.l[1]&1);goto done;}}struct pollfd fd={ConnectionNumber(d),POLLIN,0};poll(&fd,1,20);}
done: XDestroyWindow(d,source);XCloseDisplay(d);free(bytes);if(!ok)fprintf(stderr,"Xdnd transfer failed/timed out\n");return ok?0:1;}
